      "path": "package.json",
      "content": "{\n  \"name\": \"@linxin666/dsh-client-ui-activity-heatmap\",\n  \"description\": \"Activity heatmap for the dsh web GUI sidebar: a persistent GitHub-style year grid switching between daily commits / token usage / estimated spend, plus a today line with all-session token totals, cache hit rate, and per-model auto-priced cost. Data is aggregated host-side from the durable session logs (provider usage) and the workspace git repositories, served at /activity-heatmap/stats. Hot-pluggable - mounted via ~/.dsh/cordis.patch.yml + a profile node_modules symlink, no dsh source changes. Pricing table follows the xiufengsun/TokenTracker curated rates.\",\n  \"version\": \"0.1.0\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.build.json && tsdown\",\n    \"watch\": \"tsdown --watch\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-runtime\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session-persistence\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-subprocess\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-runtime\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session-persistence\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-subprocess\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.5\",\n    \"jsdom\": \"^25.0.0\",\n    \"lightningcss\": \"1.32.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"schemastery\": \"^3.18.0\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"~5.7.2\",\n    \"vitest\": \"^3.0.0\"\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"lib/**/*.js.map\",\n    \"lib/**/*.d.ts\",\n    \"lib/**/*.d.ts.map\",\n    \"src\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"plugin\",\n    \"heatmap\",\n    \"activity\",\n    \"token\",\n    \"usage\",\n    \"cost\",\n    \"github-style\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/283Gawin/dsh-heatmap.git\"\n  },\n  \"homepage\": \"https://github.com/283Gawin/dsh-heatmap\"\n}\n"
