      "path": "src/host/stats-service.ts",
      "content": "/**\n * Host stats service: scans every stored session's durable log for provider\n * token usage (assistant/message events with usage, model attribution from\n * request/header / request/context), scans the workspaces' git repositories\n * for daily commit counts, folds everything into aligned day buckets, and\n * serves a TTL-cached snapshot to the browser half.\n *\n * Reads go through the official `sessionPersistence` service (zstd decoding\n * included), git through the managed `subprocess` seam — no direct file\n * parsing, no source changes.\n * @module dsh-activity-heatmap/host/stats-service\n */\n\nimport { stat } from 'node:fs/promises'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-session-persistence'\nimport type {} from '@deepseek-ai/dsh-subprocess'\nimport {\n  assemblePayload,\n  dateKey,\n  emptyBuckets,\n  foldCommitsInto,\n  foldSessionUsages,\n  foldSamplesInto,\n  parseGitLogDates,\n} from '../core/aggregate.ts'\nimport { resolvePriceTable, type ModelPrice } from '../core/pricing.ts'\nimport type { HeatmapConfig, HeatmapPayload } from '../core/types.ts'\n\n/** Snapshot freshness window; a scan runs at most once per window. */\nconst TTL_MS = 60_000\n/** Concurrency cap while scanning session logs. */\nconst SESSION_CONCURRENCY = 4\n/** Days the heatmap covers. */\nconst WINDOW_DAYS = 365\n/** Git log output cap (a year of short dates is tiny; 1 MiB is generous). */\nconst GIT_OUTPUT_CAP = 1 << 20\n\n/** One scanned session: log signature plus folded usage samples. */\ninterface SessionScanState {\n  /** Durable log stat signature (size + mtimeMs) used for incremental re-scans. */\n  signature: string\n  samples: ReturnType<typeof foldSessionUsages>\n}\n\n/** The subprocess seam git runs through. */\nexport interface GitRunner {\n  run(argv: readonly string[], cwd: string): Promise<{ exitCode: number | null; stdout: string; stderr: string }>\n}\n\n/** Production git runner over ctx.subprocess. */\nexport function subprocessGitRunner(ctx: Context): GitRunner {\n  return {\n    async run(argv, cwd) {\n      const handle = ctx.subprocess.spawn({\n        argv: ['git', ...argv],\n        cwd,\n        stdio: {\n          stdin: 'ignore',\n          stdout: { maxBytes: GIT_OUTPUT_CAP },\n          stderr: { maxBytes: GIT_OUTPUT_CAP },\n        },\n        graceMs: 15_000,\n      })\n      const outcome = await handle.done\n      return {\n        exitCode: outcome.exitCode,\n        stdout: handle.collected.stdout?.readFrom(0).text ?? '',\n        stderr: handle.collected.stderr?.readFrom(0).text ?? '',\n      }\n    },\n  }\n}\n\n/**\n * The stats service. One instance per plugin application; owns the snapshot\n * cache and the incremental scan state.\n */\nexport class StatsService {\n  private readonly persistence: NonNullable<Context['sessionPersistence']>\n  private readonly git: GitRunner\n  private readonly config: () => HeatmapConfig\n  private readonly table: () => Record<string, ModelPrice>\n  private cache: { payload: HeatmapPayload; at: number } | undefined\n  private inflight: Promise<HeatmapPayload> | undefined\n  private readonly sessionStates = new Map<string, SessionScanState>()\n  /** Workspace roots discovered from session headers (cwd) plus config extras. */\n  private readonly repoRoots = new Set<string>()\n\n  constructor(\n    ctx: Context,\n    config: () => HeatmapConfig,\n    git: GitRunner = subprocessGitRunner(ctx),\n  ) {\n    this.persistence = ctx.sessionPersistence\n    this.config = config\n    this.git = git\n    this.table = () => resolvePriceTable(config().priceOverrides)\n  }\n\n  /** Snapshot with TTL caching; concurrent callers share one scan. */\n  async snapshot(): Promise<HeatmapPayload> {\n    const cached = this.cache\n    if (cached !== undefined && Date.now() - cached.at < TTL_MS) return cached.payload\n    if (this.inflight !== undefined) return this.inflight\n    this.inflight = this.scan()\n      .then((payload) => {\n        this.cache = { payload, at: Date.now() }\n        return payload\n      })\n      .finally(() => {\n        this.inflight = undefined\n      })\n    return this.inflight\n  }\n\n  /** Drop the cache (settings changed); the next snapshot rescans. */\n  invalidate(): void {\n    this.cache = undefined\n  }\n\n  /** Full incremental scan: changed sessions re-read, new sessions added, git rescanned. */\n  private async scan(): Promise<HeatmapPayload> {\n    const now = Date.now()\n    const days = emptyBuckets(WINDOW_DAYS, now)\n    const samples = await this.scanSessions()\n    const table = this.table()\n    foldSamplesInto(days, samples, table)\n\n    const roots = await this.collectRepos()\n    const commitDates: string[] = []\n    const since = dateKey(now - (WINDOW_DAYS - 1) * 86_400_000)\n    for (const root of roots) {\n      const argv = ['log', '--since=' + since + ' 00:00:00', '--date=short', '--pretty=format:%ad']\n      if (!(this.config().includeMerges ?? false)) argv.push('--no-merges')\n      try {\n        const result = await this.git.run(argv, root)\n        if (result.exitCode === 0) {\n          commitDates.push(...parseGitLogDates(result.stdout))\n        }\n        // Non-zero (not a repository / no commits) is a normal absence.\n      } catch {\n        // A failed git run must not take the whole snapshot down.\n      }\n    }\n    foldCommitsInto(days, commitDates)\n\n    const todaySamples = samples.filter((sample) => dateKey(sample.time) === dateKey(now))\n    return assemblePayload(days, todaySamples, table, now, this.config().usdCnyRate ?? 0)\n  }\n\n  /** Re-read only sessions whose durable log changed since the last scan. */\n  private async scanSessions() {\n    const headers = await this.persistence.list()\n    const all: ReturnType<typeof foldSessionUsages> = []\n\n    // Discover repo roots from headers and refresh per-session signatures.\n    const pending: { id: SessionId; signature: string }[] = []\n    for (const header of headers) {\n      if (typeof header.cwd === 'string' && header.cwd !== '') this.repoRoots.add(header.cwd)\n      let signature = ''\n      const location = this.persistence.locate(header)\n      if (location !== undefined) {\n        try {\n          const info = await stat(location.path)\n          signature = info.size + ':' + info.mtimeMs\n        } catch {\n          // The log may not be materialized yet; treat as new next round.\n        }\n      }\n      const state = this.sessionStates.get(header.id)\n      if (state !== undefined && state.signature === signature) {\n        all.push(...state.samples)\n        continue\n      }\n      pending.push({ id: header.id, signature })\n    }\n\n    let cursor = 0\n    const workers = Array.from({ length: Math.min(SESSION_CONCURRENCY, Math.max(1, pending.length)) }, async () => {\n      while (cursor < pending.length) {\n        const item = pending[cursor]\n        cursor += 1\n        try {\n          const { events } = await this.persistence.readFrom(item.id, 0)\n          const samples = foldSessionUsages(events)\n          this.sessionStates.set(item.id, { signature: item.signature, samples })\n          all.push(...samples)\n        } catch (error) {\n          logError('session scan failed for ' + item.id + ': ' + String(error))\n        }\n      }\n    })\n    await Promise.all(workers)\n\n    // Drop states for sessions that disappeared.\n    const live = new Set(headers.map((header) => String(header.id)))\n    for (const id of [...this.sessionStates.keys()]) {\n      if (!live.has(id)) this.sessionStates.delete(id)\n    }\n    return all\n  }\n\n  /** Repo roots: session cwds (deduped, up to a sane cap) plus configured extras. */\n  private async collectRepos(): Promise<string[]> {\n    const roots = [...this.repoRoots]\n    for (const extra of this.config().extraRepos ?? []) {\n      if (extra !== '' && !roots.includes(extra)) roots.push(extra)\n    }\n    return roots.slice(0, 64)\n  }\n}\n\n/** Log sink (swappable for tests). */\nlet logError: (message: string) => void = (message) => console.error('[dsh-activity-heatmap] ' + message)\nexport function setStatsLogger(sink: (message: string) => void): void {\n  logError = sink\n}"
    },
    {
      "path": "src/core/aggregate.ts",
      "content": "/**\n * Pure aggregation folds for the heatmap: session-event usage extraction,\n * per-day bucketing, git log date parsing, and the today summary. All\n * functions are side-effect free so the folds are unit-testable without a\n * session backend.\n * @module dsh-activity-heatmap/core/aggregate\n */\n\nimport type { SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { TokenUsage } from '@deepseek-ai/dsh-llm'\nimport { billedTokens, costUsd, priceFor, type ModelPrice } from './pricing.ts'\nimport type { DayUsage, HeatmapPayload, TodayModelRow, TodaySummary } from './types.ts'\n\n/** One provider-reported usage sample with its model attribution. */\nexport interface UsageSample {\n  /** Unix epoch ms of the carrying event. */\n  time: number\n  inputTokens: number\n  cacheReadTokens: number\n  cacheWriteTokens: number\n  outputTokens: number\n  /** Model id tracked from the nearest request/header or request/context. */\n  model: string\n}\n\nconst UNKNOWN_MODEL = 'unknown'\n\n/** Local calendar-day key for an epoch-ms timestamp ('YYYY-MM-DD'). */\nexport function dateKey(time: number): string {\n  const d = new Date(time)\n  const y = d.getFullYear()\n  const m = String(d.getMonth() + 1).padStart(2, '0')\n  const day = String(d.getDate()).padStart(2, '0')\n  return `${y}-${m}-${day}`\n}\n\n/**\n * Fold one session's durable events into usage samples.\n *\n * Provider usage rides `assistant/message` events; the model for each sample\n * is the nearest preceding `request/header` (every step logs one) or\n * `request/context`. A repeated usage for the same turn/step replaces the\n * earlier sample (retry semantics) instead of double counting.\n * @param events - the session's durable events in seq order.\n * @returns usage samples in first-seen turn/step order.\n */\nexport function foldSessionUsages(events: readonly SessionEvent[]): UsageSample[] {\n  let model = UNKNOWN_MODEL\n  const latest = new Map<string, UsageSample>()\n  for (const event of events) {\n    switch (event.type) {\n      case 'request/header': {\n        const config = event.data.header?.config\n        if (config !== undefined && typeof config.model === 'string' && config.model !== '') {\n          model = config.model\n        }\n        break\n      }\n      case 'request/context': {\n        if (typeof event.data.model === 'string' && event.data.model !== '') {\n          model = event.data.model\n        }\n        break\n      }\n      case 'assistant/message': {\n        const usage: TokenUsage | undefined = event.data.usage\n        if (usage === undefined) break\n        const key = `${event.data.turn}:${event.data.step}`\n        latest.set(key, {\n          time: event.time,\n          inputTokens: usage.inputTokens ?? 0,\n          cacheReadTokens: usage.cacheReadTokens ?? 0,\n          cacheWriteTokens: usage.cacheWriteTokens ?? 0,\n          outputTokens: usage.outputTokens ?? 0,\n          model,\n        })\n        break\n      }\n      default:\n        break\n    }\n  }\n  return [...latest.values()]\n}\n\n/** Merge one usage sample into a day bucket. */\nexport function mergeSample(day: DayUsage, sample: UsageSample, price: ModelPrice): void {\n  day.inputTokens += sample.inputTokens\n  day.cacheReadTokens += sample.cacheReadTokens\n  day.cacheWriteTokens += sample.cacheWriteTokens\n  day.outputTokens += sample.outputTokens\n  const usd = costUsd(sample, price)\n  day.modelCostUsd[sample.model] = (day.modelCostUsd[sample.model] ?? 0) + usd\n}\n\n/** Billed token total for one day (all four components). */\nexport function billedFor(day: DayUsage): number {\n  return day.inputTokens + day.cacheReadTokens + day.cacheWriteTokens + day.outputTokens\n}\n\n/**\n * Build a 365-day (or custom-length) bucket array aligned to the local\n * calendar, oldest first, ending today. Buckets are fresh zeroed rows; the\n * caller folds samples and commits into them.\n * @param dayCount - number of days to cover (default 365).\n * @param now - anchor timestamp (defaults to Date.now()).\n */\nexport function emptyBuckets(dayCount: number, now: number = Date.now()): DayUsage[] {\n  const today = new Date(now)\n  today.setHours(0, 0, 0, 0)\n  const days: DayUsage[] = []\n  for (let i = dayCount - 1; i >= 0; i -= 1) {\n    const d = new Date(today)\n    d.setDate(today.getDate() - i)\n    days.push({\n      date: dateKey(d.getTime()),\n      inputTokens: 0,\n      cacheReadTokens: 0,\n      cacheWriteTokens: 0,\n      outputTokens: 0,\n      commits: 0,\n      modelCostUsd: {},\n    })\n  }\n  return days\n}\n\n/** Index a bucket array by its date key. */\nexport function indexBuckets(days: readonly DayUsage[]): Map<string, DayUsage> {\n  return new Map(days.map((day) => [day.date, day]))\n}\n\n/** Fold all usage samples into the aligned buckets (in place). */\nexport function foldSamplesInto(\n  days: readonly DayUsage[],\n  samples: readonly UsageSample[],\n  table: Record<string, ModelPrice>,\n): void {\n  const index = indexBuckets(days)\n  for (const sample of samples) {\n    const day = index.get(dateKey(sample.time))\n    if (day === undefined) continue // older than the window: ignore\n    mergeSample(day, sample, table[sample.model] ?? priceFor(sample.model, undefined))\n  }\n}\n\n/**\n * Parse `git log --date=short --pretty=format:%ad` output into date keys.\n * Non-date lines (warnings, empty lines) are ignored.\n */\nexport function parseGitLogDates(output: string): string[] {\n  const dates: string[] = []\n  for (const line of output.split(/\\r?\\n/)) {\n    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(line)) dates.push(line)\n  }\n  return dates\n}\n\n/** Fold parsed commit dates into the aligned buckets (in place). */\nexport function foldCommitsInto(days: readonly DayUsage[], dates: readonly string[]): void {\n  const index = indexBuckets(days)\n  for (const date of dates) {\n    const day = index.get(date)\n    if (day !== undefined) day.commits += 1\n  }\n}\n\n/**\n * Build the today summary directly from today's usage samples, keeping the\n * per-model token split accurate.\n * @param samples - usage samples whose dateKey equals today.\n * @param table - resolved price table.\n * @param now - anchor timestamp.\n */\nexport function buildTodayFromSamples(\n  samples: readonly UsageSample[],\n  table: Record<string, ModelPrice>,\n  now: number = Date.now(),\n): TodaySummary {\n  const today = dateKey(now)\n  const perModel = new Map<string, { tokens: number; usd: number; input: number; cacheRead: number; cacheWrite: number; output: number }>()\n  let input = 0\n  let output = 0\n  let cacheRead = 0\n  let cacheWrite = 0\n  for (const sample of samples) {\n    if (dateKey(sample.time) !== today) continue\n    input += sample.inputTokens\n    output += sample.outputTokens\n    cacheRead += sample.cacheReadTokens\n    cacheWrite += sample.cacheWriteTokens\n    const row = perModel.get(sample.model) ?? { tokens: 0, usd: 0, input: 0, cacheRead: 0, cacheWrite: 0, output: 0 }\n    row.tokens += billedTokens(sample)\n    row.usd += costUsd(sample, table[sample.model] ?? priceFor(sample.model, undefined))\n    row.input += sample.inputTokens\n    row.cacheRead += sample.cacheReadTokens\n    row.cacheWrite += sample.cacheWriteTokens\n    row.output += sample.outputTokens\n    perModel.set(sample.model, row)\n  }\n  const prompt = input + cacheRead + cacheWrite\n  const models: TodayModelRow[] = [...perModel.entries()]\n    .map(([model, row]) => ({ model, tokens: row.tokens, usd: row.usd }))\n    .sort((a, b) => b.usd - a.usd)\n  return {\n    tokens: input + output + cacheRead + cacheWrite,\n    inputTokens: input,\n    outputTokens: output,\n    cacheReadTokens: cacheRead,\n    cacheWriteTokens: cacheWrite,\n    cacheHitRate: prompt > 0 ? cacheRead / prompt : 0,\n    costUsd: models.reduce((sum, row) => sum + row.usd, 0),\n    models,\n  }\n}\n\n/** Assemble the complete payload from folded buckets and today samples. */\nexport function assemblePayload(\n  days: readonly DayUsage[],\n  todaySamples: readonly UsageSample[],\n  table: Record<string, ModelPrice>,\n  now: number = Date.now(),\n  cnyRate: number = 0,\n): HeatmapPayload {\n  return {\n    days: days.map((day) => ({\n      date: day.date,\n      inputTokens: day.inputTokens,\n      cacheReadTokens: day.cacheReadTokens,\n      cacheWriteTokens: day.cacheWriteTokens,\n      outputTokens: day.outputTokens,\n      commits: day.commits,\n      modelCostUsd: day.modelCostUsd,\n    })),\n    today: buildTodayFromSamples(todaySamples, table, now),\n    generatedAt: now,\n    dayCount: days.length,\n    cnyRate,\n  }\n}"
    },
    {
      "path": "src/client/heatmap.ts",
      "content": "/**\n * The sidebar heatmap panel — Codex Token Activity style.\n *\n * Renders a ~91-day GitHub-style grid that can switch between commit counts,\n * billed token totals, and estimated USD spend, plus a stats block with\n * today's totals, cache hit rate, per-model cost breakdown, and the trailing\n * window sums. All data comes from GET /activity-heatmap/stats served by the\n * host half; the panel polls every POLL_MS and on visibility change.\n *\n * The panel is plain DOM (no React tree) so it can never disturb the shell's\n * reconciliation; it is mounted by sidebar.ts into the sidebar column.\n *\n * @module dsh-activity-heatmap/client/heatmap\n */\n\nimport { HEATMAP_DAYS, type DayUsage, type HeatmapMetric, type HeatmapPayload, type HeatmapTheme, type HeatmapView } from '../core/types.ts'\nimport css from './styles.module.css'\n\n/** Poll interval for the stats endpoint. */\nconst POLL_MS = 60_000\n\nconst METRIC_KEY = 'dsh.activityHeatmap.metric'\nconst VIEW_KEY = 'dsh.activityHeatmap.view'\nconst THEME_KEY = 'dsh.activityHeatmap.theme'\nconst COLLAPSED_KEY = 'dsh.activityHeatmap.collapsed'\n\n/** Stable selector identifying the mounted panel (self-heal + tests). */\nexport const PANEL_SELECTOR = '[data-dsh-heatmap-panel]'\n\n/** Bumped on every client rewrite so a stale cached bundle is easy to spot. */\nexport const PANEL_VERSION = '2'\n\nfunction formatTokens(n: number): string {\n  if (n >= 1_000_000) return (n / 1_000_000).toFixed(2) + 'M'\n  if (n >= 1_000) return (n / 1_000).toFixed(1) + 'K'\n  return String(Math.round(n))\n}\n\nfunction formatUsd(n: number): string {\n  if (n < 0.001) return '$0'\n  if (n < 0.01) return '$' + n.toFixed(3).replace(/0+$/, '').replace(/\\.$/, '')\n  if (n < 100) return '$' + n.toFixed(2)\n  return '$' + n.toFixed(1)\n}\n\nfunction billed(day: DayUsage): number {\n  return day.inputTokens + day.cacheReadTokens + day.cacheWriteTokens + day.outputTokens\n}\n\nfunction dayCost(day: DayUsage): number {\n  return Object.values(day.modelCostUsd).reduce((s, u) => s + u, 0)\n}\n\nfunction dayValue(day: DayUsage, m: HeatmapMetric): number {\n  switch (m) {\n    case 'commits': return day.commits\n    case 'tokens': return billed(day)\n    case 'cost': return dayCost(day)\n  }\n}\n\nfunction parseDate(key: string): Date {\n  const [y, mo, d] = key.split('-').map(Number)\n  return new Date(y, mo - 1, d)\n}\n\n/** Slice the payload to the trailing window. */\nfunction windowDays(payload: HeatmapPayload): DayUsage[] {\n  return payload.days.slice(Math.max(0, payload.days.length - HEATMAP_DAYS))\n}\n\n/** Grid cell levels per view mode; one number per day cell (0 = empty). */\nfunction computeValues(days: DayUsage[], metric: HeatmapMetric, view: HeatmapView): number[] {\n  if (view === 'cumulative') {\n    let sum = 0\n    return days.map(d => { sum += dayValue(d, metric); return sum })\n  }\n  if (view === 'weekly') {\n    const weekTotals = new Map<number, number>()\n    for (let i = 0; i < days.length; i++) {\n      const week = Math.floor(i / 7)\n      weekTotals.set(week, (weekTotals.get(week) ?? 0) + dayValue(days[i], metric))\n    }\n    return days.map((_, i) => weekTotals.get(Math.floor(i / 7)) ?? 0)\n  }\n  return days.map(d => dayValue(d, metric))\n}\n\n/** Level0..4 for a value on a log scale. */\nfunction level(value: number, maxLog: number): number {\n  if (value <= 0 || maxLog <= 0) return 0\n  return 1 + Math.floor(Math.min(1, Math.log10(value) / maxLog) * 3.999)\n}\n\nfunction tooltip(day: DayUsage, metric: HeatmapMetric, value: number): string {\n  const lines = [day.date]\n  lines.push('commits: ' + day.commits)\n  lines.push('tokens: ' + billed(day).toLocaleString('en-US'))\n  const cost = dayCost(day)\n  if (cost > 0) lines.push('cost: ' + formatUsd(cost))\n  if (metric !== 'tokens') lines.push(metric + ': ' + value)\n  return lines.join('\\n')\n}\n\n/** The sidebar heatmap panel. Owns its DOM, poll timer, and render state. */\nexport class HeatmapPanel {\n  readonly element: HTMLElement\n  private readonly metricBtns = new Map<HeatmapMetric, HTMLButtonElement>()\n  private readonly viewBtns = new Map<HeatmapView, HTMLButtonElement>()\n  private readonly toolbar: HTMLElement\n  private readonly gridEl: HTMLElement\n  private readonly labelsEl: HTMLElement\n  private readonly todayEl: HTMLElement\n  private readonly windowEl: HTMLElement\n  private readonly modelEl: HTMLElement\n  private readonly statsBlock: HTMLElement\n  private readonly statusEl: HTMLElement\n  private metric: HeatmapMetric\n  private view: HeatmapView\n  private theme: HeatmapTheme\n  private collapsed: boolean\n  private payload: HeatmapPayload | undefined\n  private timer: number | undefined\n  private disposed = false\n\n  constructor(initialTheme: HeatmapTheme = 'blue') {\n    this.metric = readLS(METRIC_KEY, 'commits', v => v === 'commits' || v === 'tokens' || v === 'cost')\n    this.view = readLS(VIEW_KEY, 'daily', v => v === 'daily' || v === 'weekly' || v === 'cumulative')\n    this.theme = readLS(THEME_KEY, initialTheme, v => v === 'blue' || v === 'green')\n    this.collapsed = localStorage.getItem(COLLAPSED_KEY) === '1'\n\n    this.element = document.createElement('div')\n    this.element.dataset.dshHeatmapPanel = PANEL_VERSION\n    this.element.dataset.metric = this.metric\n    this.element.dataset.theme = this.theme\n    this.element.className = css.panel\n\n    // ── Header: title left, view tabs right ──\n    const header = document.createElement('div')\n    header.className = css.header\n    header.title = 'Click to collapse/expand'\n    const chevron = document.createElement('span')\n    chevron.className = css.chevron\n    const title = document.createElement('span')\n    title.className = css.title\n    title.textContent = 'Token 活动'\n    header.append(chevron, title)\n\n    const viewGroup = document.createElement('span')\n    viewGroup.className = css.viewTabs\n    for (const [key, label] of [['daily', '每日'], ['weekly', '每周'], ['cumulative', '累计']] as const) {\n      const btn = document.createElement('button')\n      btn.type = 'button'\n      btn.className = css.viewBtn\n      btn.textContent = label\n      btn.addEventListener('click', () => this.setView(key))\n      this.viewBtns.set(key, btn)\n      viewGroup.appendChild(btn)\n    }\n    header.append(viewGroup)\n    header.addEventListener('click', (e) => {\n      if (e.target === header || e.target === title || e.target === chevron) {\n        this.collapsed = !this.collapsed\n        localStorage.setItem(COLLAPSED_KEY, this.collapsed ? '1' : '0')\n        this.applyCollapsed()\n      }\n    })\n\n    // ── Metric selector ──\n    const toolbar = document.createElement('div')\n    toolbar.className = css.toolbar\n    const metricGroup = document.createElement('span')\n    metricGroup.className = css.metricGroup\n    for (const [key, label] of [['commits', '提交'], ['tokens', 'Token'], ['cost', '花费']] as const) {\n      const btn = document.createElement('button')\n      btn.type = 'button'\n      btn.className = css.metricBtn\n      btn.textContent = label\n      btn.addEventListener('click', () => this.setMetric(key))\n      this.metricBtns.set(key, btn)\n      metricGroup.appendChild(btn)\n    }\n    // Theme is chosen in the settings page (activity-heatmap namespace), not here.\n    toolbar.append(metricGroup)\n    this.toolbar = toolbar\n\n    // ── Heatmap grid + month labels ──\n    this.gridEl = document.createElement('div')\n    this.gridEl.className = css.grid\n    this.labelsEl = document.createElement('div')\n    this.labelsEl.className = css.labels\n\n    // ── Stats block ──\n    const stats = document.createElement('div')\n    stats.className = css.stats\n    this.todayEl = document.createElement('div')\n    this.todayEl.className = css.statsRow\n    this.windowEl = document.createElement('div')\n    this.windowEl.className = css.statsRow\n    this.modelEl = document.createElement('div')\n    this.modelEl.className = css.modelLine\n    stats.append(this.todayEl, this.windowEl, this.modelEl)\n    this.statsBlock = stats\n\n    this.statusEl = document.createElement('div')\n    this.statusEl.className = css.status\n    this.statusEl.textContent = '统计中…'\n\n    this.element.append(header, toolbar, this.gridEl, this.labelsEl, stats, this.statusEl)\n    this.applyCollapsed()\n    this.applyButtons()\n  }\n\n  /** Begin polling and attach the visibility listener. */\n  start(): void {\n    void this.refresh()\n    this.timer = window.setInterval(() => { void this.refresh() }, POLL_MS)\n    document.addEventListener('visibilitychange', this.onVis)\n  }\n\n  dispose(): void {\n    this.disposed = true\n    if (this.timer !== undefined) clearInterval(this.timer)\n    document.removeEventListener('visibilitychange', this.onVis)\n    this.element.remove()\n  }\n\n  private readonly onVis = (): void => {\n    if (document.visibilityState === 'visible') void this.refresh()\n  }\n\n  private setMetric(m: HeatmapMetric): void {\n    if (m === this.metric) return\n    this.metric = m\n    localStorage.setItem(METRIC_KEY, m)\n    this.element.dataset.metric = m\n    this.applyButtons()\n    this.render()\n  }\n\n  private setView(v: HeatmapView): void {\n    if (v === this.view) return\n    this.view = v\n    localStorage.setItem(VIEW_KEY, v)\n    this.applyButtons()\n    this.render()\n  }\n\n  setTheme(t: HeatmapTheme): void {\n    if (t === this.theme) return\n    this.theme = t\n    localStorage.setItem(THEME_KEY, t)\n    this.element.dataset.theme = t\n    this.applyButtons()\n  }\n\n  private applyButtons(): void {\n    for (const [k, b] of this.metricBtns) b.classList.toggle(css.active, k === this.metric)\n    for (const [k, b] of this.viewBtns) b.classList.toggle(css.active, k === this.view)\n  }\n\n  private applyCollapsed(): void {\n    const hide = this.collapsed\n    for (const el of [this.toolbar, this.gridEl, this.labelsEl, this.statsBlock, this.statusEl]) {\n      el.style.display = hide ? 'none' : ''\n    }\n    this.element.querySelector('.' + css.chevron)?.classList.toggle(css.chevronOpen, hide)\n  }\n\n  private async refresh(): Promise<void> {\n    if (this.disposed) return\n    try {\n      const r = await fetch('/activity-heatmap/stats', { headers: { accept: 'application/json' }, cache: 'no-store' })\n      if (!r.ok) throw new Error('HTTP ' + r.status)\n      const env = await r.json() as { ok: boolean; value?: HeatmapPayload }\n      if (!env.ok || !env.value) throw new Error('bad')\n      this.payload = env.value\n      this.statusEl.textContent = ''\n      this.render()\n    } catch {\n      if (!this.disposed) this.statusEl.textContent = '数据不可用'\n    }\n  }\n\n  private render(): void {\n    this.gridEl.replaceChildren()\n    this.labelsEl.replaceChildren()\n    const p = this.payload\n    if (!p) return\n\n    const days = windowDays(p)\n    const vals = computeValues(days, this.metric, this.view)\n    const maxLog = Math.max(...vals.filter(v => v > 1).map(v => Math.log10(v)), 0)\n\n    // Week-alignment padding: pad first column up to Monday.\n    if (days.length > 0) {\n      const first = parseDate(days[0].date)\n      const pad = (first.getDay() + 6) % 7\n      for (let i = 0; i < pad; i++) {\n        const cell = document.createElement('div')\n        cell.className = css.cell\n        this.gridEl.appendChild(cell)\n      }\n    }\n\n    // Cells\n    for (let i = 0; i < days.length; i++) {\n      const cell = document.createElement('div')\n      cell.className = css.cell\n      const lv = level(vals[i], maxLog)\n      if (lv > 0) cell.classList.add(css['l' + lv])\n      cell.title = tooltip(days[i], this.metric, vals[i])\n      this.gridEl.appendChild(cell)\n    }\n\n    // Monthly labels\n    this.renderLabels(days)\n\n    // Stats block\n    const today = p.today\n    const hitRate = Math.round(today.cacheHitRate * 1000) / 10\n    const cny = today.costUsd >= 0.001 && p.cnyRate > 0 ? ' · ¥' + (today.costUsd * p.cnyRate).toFixed(2) : ''\n    this.todayEl.replaceChildren(\n      statItem('今日 Token', formatTokens(today.tokens)),\n      statItem('缓存命中', hitRate + '%'),\n      statItem('今日花费', formatUsd(today.costUsd) + cny),\n    )\n    let tokens = 0, commits = 0, cost = 0\n    for (const d of days) { tokens += billed(d); commits += d.commits; cost += dayCost(d) }\n    this.windowEl.replaceChildren(\n      statItem('Token 合计', formatTokens(tokens)),\n      statItem('提交数', String(commits)),\n      statItem('花费合计', formatUsd(cost)),\n    )\n    if (today.models.length > 0) {\n      this.modelEl.textContent = today.models.map(r => r.model + ' ' + formatUsd(r.usd)).join(' · ')\n    } else {\n      this.modelEl.textContent = ''\n    }\n  }\n\n  private renderLabels(days: DayUsage[]): void {\n    if (days.length === 0) return\n    const gridRect = this.gridEl.getBoundingClientRect()\n    const gridLeft = gridRect.left\n    const cells = Array.from(this.gridEl.children) as HTMLElement[]\n    const labels: { text: string; x: number }[] = []\n    let lastMonth = ''\n    for (let i = 0; i < days.length; i++) {\n      const mo = days[i].date.slice(0, 7)\n      if (mo !== lastMonth) {\n        lastMonth = mo\n        const cellIdx = i + ((parseDate(days[0].date).getDay() + 6) % 7)\n        const cell = cells[cellIdx]\n        if (cell) {\n          const rect = cell.getBoundingClientRect()\n          const [y, m] = mo.split('-')\n          labels.push({ text: parseInt(m) + '\\u6708', x: rect.left - gridLeft })\n        }\n      }\n    }\n    for (const lbl of labels) {\n      const span = document.createElement('span')\n      span.className = css.monthLabel\n      span.textContent = lbl.text\n      span.style.marginLeft = lbl.x + 'px'\n      this.labelsEl.appendChild(span)\n    }\n  }\n}\n\nfunction statItem(label: string, value: string): HTMLElement {\n  const wrap = document.createElement('div')\n  wrap.className = css.statItem\n  const l = document.createElement('div')\n  l.className = css.statLabel\n  l.textContent = label\n  const v = document.createElement('div')\n  v.className = css.statValue\n  v.textContent = value\n  wrap.append(l, v)\n  return wrap\n}\n\nfunction readLS<T extends string>(key: string, fallback: T, guard: (v: string) => v is T): T {\n  try { const v = localStorage.getItem(key); if (v !== null && guard(v)) return v } catch {}\n  return fallback\n}\n"
    },
    {
      "path": "src/core/types.ts",
      "content": "/**\n * Shared vocabulary between the host stats service and the browser heatmap\n * panel. Everything crossing the /activity-heatmap/* wire is declared here so\n * the two halves cannot drift.\n * @module dsh-activity-heatmap/core/types\n */\n\n/** One calendar day's aggregated activity. */\nexport interface DayUsage {\n  date: string\n  inputTokens: number\n  cacheReadTokens: number\n  cacheWriteTokens: number\n  outputTokens: number\n  commits: number\n  modelCostUsd: Record<string, number>\n}\n\n/** One model's contribution to the current day. */\nexport interface TodayModelRow {\n  model: string\n  tokens: number\n  usd: number\n}\n\n/** The \"today\" summary line under the heatmap. */\nexport interface TodaySummary {\n  tokens: number\n  inputTokens: number\n  outputTokens: number\n  cacheReadTokens: number\n  cacheWriteTokens: number\n  cacheHitRate: number\n  costUsd: number\n  models: TodayModelRow[]\n}\n\n/** Full payload the panel renders. */\nexport interface HeatmapPayload {\n  days: DayUsage[]\n  today: TodaySummary\n  generatedAt: number\n  dayCount: number\n  cnyRate: number\n}\n\n/** The heatmap metric a user can switch between. */\nexport type HeatmapMetric = 'commits' | 'tokens' | 'cost'\n\n/** Aggregation view mode matching Codex's Token Activity panel. */\nexport type HeatmapView = 'daily' | 'weekly' | 'cumulative'\n\n/** Color theme: blue (Codex default) or green (GitHub default). */\nexport type HeatmapTheme = 'blue' | 'green'\n\n/** Days the heatmap covers. ~13 weeks, fits the sidebar width. */\nexport const HEATMAP_DAYS = 91\n\n/** HTTP envelope shared by the route layer. */\nexport type StatsEnvelope<T> =\n  | { ok: true; value: T }\n  | { ok: false; error: { code: string; message: string } }\n\n/** Live plugin configuration the host applies. */\nexport interface HeatmapConfig {\n  theme?: HeatmapTheme\n  enabled?: boolean\n  includeMerges?: boolean\n  extraRepos?: string[]\n  usdCnyRate?: number\n  priceOverrides?: Record<string, {\n    inputPerM?: number\n    cacheReadPerM?: number\n    cacheWritePerM?: number\n    outputPerM?: number\n  }>\n}"
    },
    {
      "path": "src/core/pricing.ts",
      "content": "/**\n * Model pricing table and spend estimation.\n *\n * Built-in rows follow each vendor's published API pricing (USD per 1M\n * tokens, as of 2025-2026 public price sheets). Providers bill cache-read\n * input at a discount and cache-write input either at a small fee (Anthropic)\n * or not at all (DeepSeek / OpenAI / Google / xAI / Chinese vendors).\n * Unknown models fall back to the default row so a novel model id never\n * crashes the estimate; users can override any row through the settings\n * namespace (`priceOverrides`).\n *\n * Model ids are matched exactly first, then by the longest built-in key that\n * is a `-`-delimited prefix of the id, so dated snapshot ids like\n * `claude-sonnet-4-5-20250929` or `gpt-5.1-20250807` still resolve to the\n * base row.\n * @module dsh-activity-heatmap/core/pricing\n */\n\n/** One model's price row, USD per 1M tokens. */\nexport interface ModelPrice {\n  /** Cache-miss input tokens. */\n  inputPerM: number\n  /** Cache-read (hit) input tokens. */\n  cacheReadPerM: number\n  /** Cache-write input tokens (DeepSeek: 0; Anthropic bills these). */\n  cacheWritePerM: number\n  /** Completion tokens. */\n  outputPerM: number\n}\n\n/** Fallback price applied to models absent from the table. */\nconst DEFAULT_PRICE: ModelPrice = { inputPerM: 0.27, cacheReadPerM: 0.07, cacheWritePerM: 0, outputPerM: 1.1 }\n\n/** Built-in price rows for the models DSH commonly routes to.\n * Rates follow the xiufengsun/TokenTracker curated price overrides\n * (verified against vendor pages 2026-06/07) plus vendor list pages.\n * Units: USD per 1M tokens. */\nexport const DEFAULT_MODEL_PRICES: Record<string, ModelPrice> = {\n  // ---- DeepSeek (official api-docs.deepseek.com, verified 2026-06-10) ----\n  // V4 series: current flat pricing (before the 2026-08-16 peak/off-peak switch).\n  'deepseek-v4-flash': { inputPerM: 0.14, cacheReadPerM: 0.0028, cacheWritePerM: 0.14, outputPerM: 0.28 },\n  'deepseek-v4-pro': { inputPerM: 0.435, cacheReadPerM: 0.003625, cacheWritePerM: 0.435, outputPerM: 0.87 },\n  'deepseek-chat': { inputPerM: 0.14, cacheReadPerM: 0.0028, cacheWritePerM: 0.14, outputPerM: 0.28 },\n  'deepseek-v3': { inputPerM: 0.27, cacheReadPerM: 0.07, cacheWritePerM: 0, outputPerM: 1.1 },\n  'deepseek-v3.1': { inputPerM: 0.56, cacheReadPerM: 0.056, cacheWritePerM: 0, outputPerM: 1.68 },\n  'deepseek-v3.2': { inputPerM: 0.28, cacheReadPerM: 0.028, cacheWritePerM: 0, outputPerM: 0.42 },\n  'deepseek-v3.2-expensive': { inputPerM: 0.56, cacheReadPerM: 0.056, cacheWritePerM: 0, outputPerM: 1.68 },\n  'deepseek-reasoner': { inputPerM: 0.14, cacheReadPerM: 0.0028, cacheWritePerM: 0.14, outputPerM: 0.28 },\n  'deepseek-r1': { inputPerM: 0.55, cacheReadPerM: 0.14, cacheWritePerM: 0, outputPerM: 2.19 },\n\n  // ---- Anthropic Claude (cache-write is billed) ----\n  'claude-3-haiku': { inputPerM: 0.25, cacheReadPerM: 0.025, cacheWritePerM: 0.3, outputPerM: 1.25 },\n  'claude-3-5-haiku': { inputPerM: 0.8, cacheReadPerM: 0.08, cacheWritePerM: 1, outputPerM: 4 },\n  'claude-3-5-sonnet': { inputPerM: 3, cacheReadPerM: 0.3, cacheWritePerM: 3.75, outputPerM: 15 },\n  'claude-3-7-sonnet': { inputPerM: 3, cacheReadPerM: 0.3, cacheWritePerM: 3.75, outputPerM: 15 },\n  'claude-3-opus': { inputPerM: 15, cacheReadPerM: 1.5, cacheWritePerM: 18.75, outputPerM: 75 },\n  'claude-sonnet-4': { inputPerM: 3, cacheReadPerM: 0.3, cacheWritePerM: 3.75, outputPerM: 15 },\n  'claude-sonnet-4-5': { inputPerM: 3, cacheReadPerM: 0.3, cacheWritePerM: 3.75, outputPerM: 15 },\n  'claude-opus-4': { inputPerM: 15, cacheReadPerM: 1.5, cacheWritePerM: 18.75, outputPerM: 75 },\n  'claude-opus-4-1': { inputPerM: 15, cacheReadPerM: 1.5, cacheWritePerM: 18.75, outputPerM: 75 },\n  'claude-opus-4-8': { inputPerM: 5, cacheReadPerM: 0.5, cacheWritePerM: 6.25, outputPerM: 25 },\n  'claude-opus-5': { inputPerM: 5, cacheReadPerM: 0.5, cacheWritePerM: 6.25, outputPerM: 25 },\n  'claude-opus-5-fast': { inputPerM: 10, cacheReadPerM: 1, cacheWr